<?php
session_start(); require 'config.php'; require 'functions.php'; verify_csrf(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(isset($_POST['delete_id'])){$st=$pdo->prepare("DELETE FROM teams WHERE team_id=?");$st->execute([int_post('delete_id')]);flash('Team deleted.');redirect('teams.php');}
  if(isset($_POST['save_team'])){$name=trim((string)post('name'));$tag=trim((string)post('tag'));$captain=int_post('captain_player_id')?:null;$id=int_post('team_id');if($name==='')throw new RuntimeException('Team name is required.');if($id){$st=$pdo->prepare("UPDATE teams SET name=?,tag=?,captain_player_id=? WHERE team_id=?");$st->execute([$name,$tag?:null,$captain,$id]);flash('Team updated.');}else{$st=$pdo->prepare("INSERT INTO teams(name,tag,captain_player_id) VALUES(?,?,?)");$st->execute([$name,$tag?:null,$captain]);flash('Team created.');}redirect('teams.php');}
  if(isset($_POST['add_member'])){$st=$pdo->prepare("INSERT INTO team_members(team_id,player_id,role) VALUES(?,?,?)");$st->execute([int_post('team_id'),int_post('player_id'),trim((string)post('role','Player'))?:'Player']);flash('Player assigned to team.');redirect('teams.php');}
  if(isset($_POST['remove_member'])){$st=$pdo->prepare("DELETE FROM team_members WHERE team_id=? AND player_id=?");$st->execute([int_post('team_id'),int_post('player_id')]);flash('Player removed from roster.');redirect('teams.php');}
 }catch(Throwable $e){$error=$e instanceof PDOException&&$e->getCode()==='23000'?'That team name, tag, or roster assignment already exists, or the team is linked to other records.':$e->getMessage();}
}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare("SELECT * FROM teams WHERE team_id=?");$st->execute([(int)$_GET['edit']]);$edit=$st->fetch()?:null;}
$players=$pdo->query("SELECT player_id,name FROM players ORDER BY name")->fetchAll();
$teams=$pdo->query("SELECT t.*,p.name captain,(SELECT COUNT(*) FROM team_members tm WHERE tm.team_id=t.team_id) members FROM teams t LEFT JOIN players p ON p.player_id=t.captain_player_id ORDER BY t.created_at DESC")->fetchAll();
$members=$pdo->query("SELECT tm.team_id,tm.player_id,tm.role,p.name FROM team_members tm JOIN players p ON p.player_id=tm.player_id ORDER BY p.name")->fetchAll();
page_header('Teams','teams');
?>
<div class="page-heading"><div><h1>Teams</h1><p>Create esports squads and manage their player rosters.</p></div><span class="tag"><?= count($teams) ?> teams</span></div>
<?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<div class="row g-4"><div class="col-xl-4"><div class="cardx"><div class="section-title"><?= $edit?'Edit team':'Create a team' ?></div><form method="post"><?= csrf_field() ?><input type="hidden" name="team_id" value="<?= e($edit['team_id']??'') ?>"><div class="mb-3"><label class="form-label">Team name *</label><input class="form-control" name="name" required value="<?= e($edit['name']??'') ?>" placeholder="e.g. Phantom Esports"></div><div class="mb-3"><label class="form-label">Team tag</label><input class="form-control" name="tag" maxlength="12" value="<?= e($edit['tag']??'') ?>" placeholder="PHX"></div><div class="mb-3"><label class="form-label">Captain (optional)</label><select class="form-select" name="captain_player_id"><option value="">Select player</option><?php foreach($players as $p): ?><option value="<?= (int)$p['player_id'] ?>" <?= (int)($edit['captain_player_id']??0)===(int)$p['player_id']?'selected':'' ?>><?= e($p['name']) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary w-100" name="save_team" value="1"><?= $edit?'Save changes':'Create team' ?></button><?php if($edit): ?><a href="teams.php" class="btn btn-outline-light w-100 mt-2">Cancel</a><?php endif; ?></form></div>
<div class="cardx mt-4"><div class="section-title">Add player to roster</div><?php if(!$teams||!$players): ?><div class="small-note">Create at least one team and one player first.</div><?php else: ?><form method="post"><?= csrf_field() ?><div class="mb-3"><label class="form-label">Team</label><select class="form-select" name="team_id" required><?php foreach($teams as $t): ?><option value="<?= (int)$t['team_id'] ?>"><?= e($t['name']) ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Player</label><select class="form-select" name="player_id" required><?php foreach($players as $p): ?><option value="<?= (int)$p['player_id'] ?>"><?= e($p['name']) ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Role</label><select class="form-select" name="role"><option>Player</option><option>Captain</option><option>Substitute</option></select></div><button class="btn btn-outline-light w-100" name="add_member" value="1"><i class="bi bi-person-plus me-1"></i>Assign player</button></form><?php endif; ?></div></div>
<div class="col-xl-8"><div class="cardx"><div class="section-title">Team directory</div><div class="table-responsive"><table class="table"><thead><tr><th>Team</th><th>Captain</th><th>Roster</th><th>Actions</th></tr></thead><tbody><?php foreach($teams as $t): ?><tr><td><div class="d-flex align-items-center gap-2"><div class="avatar"><?= e(strtoupper(substr($t['tag']?:$t['name'],0,2))) ?></div><div><div class="fw-semibold"><?= e($t['name']) ?></div><div class="small muted"><?= e($t['tag']?:'No tag') ?></div></div></div></td><td><?= e($t['captain']?:'—') ?></td><td><span class="tag"><?= (int)$t['members'] ?> players</span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-light" href="teams.php?edit=<?= (int)$t['team_id'] ?>"><i class="bi bi-pencil"></i></a> <?= delete_button('teams.php',(int)$t['team_id']) ?></td></tr><?php endforeach; ?></tbody></table><?php if(!$teams): ?><div class="empty-state">No teams created yet.</div><?php endif; ?></div></div>
<div class="cardx mt-4"><div class="section-title">Team rosters</div><?php foreach($teams as $t): $tm=array_values(array_filter($members,fn($m)=>(int)$m['team_id']===(int)$t['team_id'])); ?><div class="py-3 border-bottom" style="border-color:var(--line)!important"><div class="fw-semibold mb-2"><?= e($t['name']) ?></div><?php if(!$tm): ?><span class="small-note">No players assigned yet.</span><?php else: foreach($tm as $m): ?><span class="tag me-1 mb-1"><?= e($m['name']) ?> · <?= e($m['role']) ?> <form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="team_id" value="<?= (int)$t['team_id'] ?>"><input type="hidden" name="player_id" value="<?= (int)$m['player_id'] ?>"><button class="btn p-0 ms-1" style="color:#fda4af;font-size:10px" name="remove_member" value="1" title="Remove player">×</button></form></span><?php endforeach; endif; ?></div><?php endforeach; ?></div></div></div>
<?php page_footer(); ?>
